head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.getHeightofCell = function() {
    return parseInt(WebSquare.wUnit.getDomById($p.id + "grdList_cell_0_5").style.height);
}
scwin.getTopStyleInput = function(id) {
    return parseInt(WebSquare.wUnit.getDomById($p.id + id).style.top);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_grdList__M1_VAL', 'key-combo', {
        combo: 'DOWN_ARROW'
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#G_grdList__M2_VAL', 'key-combo', {
        combo: 'DOWN_ARROW'
    });
}
scwin.setVal1 = function() {
	topInputInit = scwin.getTopStyleInput('G_'+$p.id+'grdList__M1_VAL');
}
scwin.setVal2 = function() {
	topInputAfterChange = scwin.getTopStyleInput('G_'+$p.id+'grdList__M1_VAL');
}
scwin.setVal3 = function() {
	topInputInit = scwin.getTopStyleInput('G_'+$p.id+'grdList__M2_VAL');
}
scwin.setVal4 = function() {
	topInputAfterChange = scwin.getTopStyleInput('G_'+$p.id+'grdList__M2_VAL')
}
scwin.checkVal1 = function(id) {
    return topInputAfterChange > topInputInit + scwin.getHeightofCell()*2;
}
scwin.checkVal2 = function(id) {
    return (topInputAfterChange >= topInputInit + scwin.getHeightofCell()) && (topInputAfterChange < topInputInit + scwin.getHeightofCell()*2);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grdList_cell_9_4').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");

    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grdList_cell_9_5').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal3()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "scwin.setVal4()");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

